from scipy.optimize import least_squares
Pf={'P':P,'P2':P**2,'P3':P**3,'sqrtP':np.sqrt(P),'logP':np.log(P),'1/P':1/P,'P2e-P':P**2*np.exp(-P),'Pe-P':P*np.exp(-P),'P(6.3-P)':P*(6.3-P)}
