def fitfor(pn,tn,f0):
    def r(p):
        base=p[0]*np.sin(p[1]*t)*P+p[2]*np.log(1+t)**2
        return base+p[3]*Pf[pn]*tf[tn]-dP_dt
    return least_squares(r,[1,f0,1,0.5])
out=[]
for pn in Pf:
    for tn in tf:
        bc=None
        for f0 in [0.3,1,2.5]:
